<?php
declare(strict_types=1);
function db(): PDO {
 static $db;
 if($db)return $db;
 $url=getenv('DATABASE_URL');if(!$url)throw new RuntimeException('Database not configured');
 $p=parse_url($url);if(!$p||!isset($p['host'],$p['user'],$p['path']))throw new RuntimeException('Invalid database configuration');
 $db=new PDO('pgsql:host='.$p['host'].';port='.($p['port']??5432).';dbname='.ltrim($p['path'],'/').';sslmode=require',rawurldecode($p['user']),rawurldecode($p['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
 $db->beginTransaction();
 try{
 $db->exec("SELECT pg_advisory_xact_lock(784825)");
 $db->exec("CREATE TABLE IF NOT EXISTS q_meta (key TEXT PRIMARY KEY); CREATE TABLE IF NOT EXISTS q_categories (name TEXT PRIMARY KEY); CREATE TABLE IF NOT EXISTS q_products (id INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 9) PRIMARY KEY,name TEXT NOT NULL UNIQUE,category TEXT NOT NULL REFERENCES q_categories(name),description TEXT NOT NULL,specifications TEXT NOT NULL DEFAULT '',origin TEXT NOT NULL DEFAULT 'India',packaging TEXT NOT NULL DEFAULT 'On enquiry',moq TEXT NOT NULL DEFAULT 'On enquiry',lead_time TEXT NOT NULL DEFAULT 'On enquiry',price TEXT NOT NULL DEFAULT 'On quotation',availability TEXT NOT NULL DEFAULT 'Subject to confirmation',published BOOLEAN NOT NULL DEFAULT TRUE,featured BOOLEAN NOT NULL DEFAULT FALSE,local TEXT NOT NULL DEFAULT '',url TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT '',author TEXT NOT NULL DEFAULT '',license TEXT NOT NULL DEFAULT '',image_data TEXT,image_mime TEXT); CREATE TABLE IF NOT EXISTS q_enquiries (reference TEXT PRIMARY KEY,created BIGINT NOT NULL,iphash TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'New'); CREATE INDEX IF NOT EXISTS q_enquiry_ip ON q_enquiries(iphash,created); CREATE TABLE IF NOT EXISTS q_login_attempts (iphash TEXT NOT NULL,created BIGINT NOT NULL); CREATE INDEX IF NOT EXISTS q_login_ip ON q_login_attempts(iphash,created)");
 if(!$db->query("SELECT 1 FROM q_meta WHERE key='seed-v1'")->fetchColumn()){
 $seed=json_decode(file_get_contents(__DIR__.'/seed.json'),true,512,JSON_THROW_ON_ERROR);
 $cat=$db->prepare('INSERT INTO q_categories VALUES (?) ON CONFLICT DO NOTHING');
 $ins=$db->prepare('INSERT INTO q_products(id,name,category,description,specifications,local,url,source,author,license,featured) VALUES (?,?,?,?,?,?,?,?,?,?,?)');
 foreach($seed as $r){$cat->execute([$r['category']]);$ins->execute([$r['id'],$r['name'],$r['category'],$r['description'],$r['specifications'],$r['local'],$r['url'],$r['source'],$r['author'],$r['license'],in_array($r['id'],[0,3,5,8],true)?'true':'false']);}
 $db->exec("INSERT INTO q_meta VALUES ('seed-v1')");
 }
 $db->commit();
 }catch(Throwable $e){$db->rollBack();throw $e;}
 return $db;
}
function products(PDO $db,bool $all=false): array {
 $sql="SELECT id,name,category,description,specifications,origin,packaging,moq,lead_time,price,availability,published::int AS published,featured::int AS featured,local,url,source,author,license,(image_data IS NOT NULL)::int AS has_image FROM q_products".($all?'':' WHERE published')." ORDER BY id";
 return $db->query($sql)->fetchAll();
}
function esc(string|int|null $v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function iphash(): string {return hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'unknown',getenv('QWANTA_RATE_SECRET')?:'local-rate');}
